select business_date, abor_security_id, esm_exchange_name, mic
from (
	select *,
	row_number() over (partition by abor_security_id order by business_date desc) as rn
	from asset.enterprise_security
) es
where es.rn = 1
and abor_security_id = 'CSCH 6.5 9014'
limit 10

